        jTextArea1.setRows(5);
        jTextArea1.setText("Ingredients:\n\n1. 200g dark chocolate\n\n2. 200ml heavy cream \n(for ganache) \n\n3. 250g mascarpone\n cheese \n\n4. 200ml cold whipping\n cream \n\n5. 3 tbsp powdered sugar\n\n6.1 tsp vanilla extract \n\n7. 1 cup strong coffee \n(cooled) \n\n8. 2 tbsp coffee liqueur \n(optional)\n\n9. 200g ladyfinger biscuits \nCocoa powder (for dusting)");
        jScrollPane1.setViewportView(jTextArea1);

        jTextArea2.setColumns(20);
        jTextArea2.setFont(new java.awt.Font("Arial", 0, 12)); // NOI18N
        jTextArea2.setRows(5);
        jTextArea2.setText("Directions\n\n1.Heat cream, pour over\nchocolate,stir to make ganache.\n\n2. Whip cream with sugar \nand vanilla, fold into\nmascarpone.\n\n3.Mix coffee with liqueur\n (optional).\n\n4.Dip ladyfingers in coffe,\n layer in dish.\n\n5.Add mascarpone mixture, \nthen ganache. Repeat layers.\n\n6.Chill for 4+ hours.\n\n7.Dust with cocoa before\n serving");
        jScrollPane2.setViewportView(jTextArea2);

